/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
class METDutyAdValorumClaimGenerateService extends SysOperationServiceBase
{
    METDutyAdValorumClaimGenerateContract   dataContract;
    METDutyAdValorumClaimTmp                dutyAdValorumClaimTmp;
    List                                    itemList;
    List                                    siteList;
    boolean                                 filterItemSite;
    boolean                                 generateClaim;
    int                                     totalTasks;
    
}

Method.Source:
    // <summary>
    /// Schedules tasks
    /// <summary>
    public void scheduleTasks()
    {
        #OCCRetryCount

        METDutyAdValorumClaimGenerateContract  taskContract;
        SysOperationServiceController          controller;
        Int                                    bundlesize;
        BatchHeader                            batchHeader;
        int                                    counter = 0;
        Int                                    numOfOrders = this.getTotalRecords();
        container                              conItems;
        Set                                    tasks;

        if (totalTasks <= 0)
        {
            totalTasks = 1;
        }

        bundleSize = real2int(roundUp((numOfOrders / totalTasks), 1.0));

        Info(strFmt("Number of records: %1", numOfOrders));
        Info(strFmt("BundleSize : %1", bundleSize));

        batchHeader  = this.getCurrentBatchHeader();
        tasks = new Set(Types::Class);

        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }

        try
        {
            while select dutyAdValorumClaimTmp
            {
                counter += 1;

                if (counter == 1)
                {
                    conItems = conNull();
                }

                conItems += [dutyAdValorumClaimTmp];
    
                if (counter == bundlesize)
                {
                    controller      = new SysOperationServiceController(
                                                    classStr(METDutyAdValorumClaimGenerateJob),
                                                    methodStr(METDutyAdValorumClaimGenerateJob, process));

                    controller.parmDialogCaption(strFmt("@MET:GenerateAdValorumClaimSubTask", counter));

                    taskContract = controller.getDataContractObject() as METDutyAdValorumClaimGenerateContract;
                    
                    taskContract.parmConItems(conItems);
                    taskContract.parmDutyValuesBySite(dataContract.parmDutyValuesBySite());
                    taskContract.parmFilterItemSite(dataContract.parmFilterItemSite());
                    taskContract.parmGenerateClaims(dataContract.parmGenerateClaims());
                   
                    batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                    tasks.add(controller);

                    counter = 0;
                }
            }

            if (counter > 0)
            {
                controller      = new SysOperationServiceController(
                                                    classStr(METDutyAdValorumClaimGenerateJob),
                                                    methodStr(METDutyAdValorumClaimGenerateJob, process));

                controller.parmDialogCaption(strFmt("@MET:GenerateAdValorumClaimSubTask", counter));

                taskContract = controller.getDataContractObject() as METDutyAdValorumClaimGenerateContract;

                taskContract.parmConItems(conItems);
                taskContract.parmDutyValuesBySite(dataContract.parmDutyValuesBySite());
                taskContract.parmFilterItemSite(dataContract.parmFilterItemSite());
                taskContract.parmGenerateClaims(dataContract.parmGenerateClaims());

                batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                tasks.add(controller);
            }

            if (generateClaim)
            {
                this.scheduleFinalTaskToProcessClaims(batchHeader, tasks);
            }
              
            batchHeader.save();
        }
        catch(Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    /// <summary>
    /// Schedules final task to process claims.
    /// </summary>
    /// <param name = "_batchHeader">Batch header.</param>
    /// <param name = "_tasks">Tasks.</param>
    private void scheduleFinalTaskToProcessClaims(BatchHeader _batchHeader, Set _tasks)
    {
        METDutyAdValorumClaimGenerateContract  contract;
        SysOperationServiceController controller;
        SetEnumerator tasksEnum;
        int subTask;

        controller  = new SysOperationServiceController(
                                                    classStr(METDutyAdValorumClaimGenerateJob),
                                                    methodStr(METDutyAdValorumClaimGenerateJob, processFinalClaims));

        subTask = _tasks.elements() + 1;

        controller.parmDialogCaption(strFmt("@MET:GenerateAdValorumClaimSubTask", subTask));
        
        contract = controller.getDataContractObject() as METDutyAdValorumClaimGenerateContract;

        contract.parmPhysicalTableName(dutyAdValorumClaimTmp.getPhysicalTableName());
        _batchHeader.addTask(controller);

        tasksEnum =_tasks.getEnumerator();

        while (tasksEnum && tasksEnum.moveNext())
        {
            SysOperationServiceController taskController = tasksEnum.current();
            _batchHeader.addDependency(controller, taskController, BatchDependencyStatus::Finished);
        }
    }

    /// <summary>
    /// Generate data in tmp table.
    /// </summary>
    private void generateDataInTmp()
    {
        
        METDutyRollVariance         dutyRollVarianceGrouped;
        METDutyRollVariance         dutyRollVariance;
        METExciseSiteDutySetup      exciseSiteDutySetup;
        
        if (generateClaim)
        {
            this.deleteDutyRollVariance();
        }

        if (!filterItemSite)
        {
            insert_recordset dutyAdValorumClaimTmp (ItemId, Site)
                select ItemId, Site from dutyRollVarianceGrouped
                        group by ItemId, Site
                    where dutyRollVarianceGrouped.InventTransType == InventTransType::Purch
                        && dutyRollVarianceGrouped.ClaimCreated == NoYes::No;
        }
        else
        {
            if (!siteList.empty() && !itemList.empty())
            {
                ListEnumerator iter = siteList.getEnumerator();

                while (iter.moveNext())
                {
                    InventSiteId siteId  = iter.current();
                    this.processSite(siteId);
                }

            }
            else if (!itemList.empty())
            {
                METDutyRollVariance     dutyRollVarianceGroupedSite;

                while select dutyRollVarianceGroupedSite
                    group by Site
                    where dutyRollVarianceGroupedSite.InventTransType == InventTransType::Purch
                {
                    this.processSite(dutyRollVarianceGroupedSite.Site);
                }
            }
        }
    }

    /// <summary>
    /// main process method
    /// </summary>
    /// <param name = "_dataContract">Contract</param>
    public void processOperation(METDutyAdValorumClaimGenerateContract _dataContract)
    {
        try
        {
            ttsbegin;

            filterItemSite = _dataContract.parmFilterItemSite();
            itemList       = _dataContract.parmItemList();
            siteList       = _dataContract.parmSiteList();
            generateClaim  = _dataContract.parmGenerateClaims();
            totalTasks     = _dataContract.parmParallelTasksNumber();
            dataContract   = _dataContract;

            this.generateDataInTmp();
            this.scheduleTasks();

            ttscommit;
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }
    }

    /// <summary>
    /// Deletes duty roll variance records created before the current month.
    /// </summary>
    private void deleteDutyRollVariance()
    {
        METDutyRollVariance     dutyRollVariance;

        utcdatetime systemDateTime = DateTimeUtil::getSystemDateTime();
        utcdatetime dateTimeStartMth = DateTimeUtil::newDateTime(DateTimeUtil::date(DateTimeUtil::addDays(systemDateTime, 1 - DateTimeUtil::day(systemDateTime))), 0);
        
        ttsbegin;
        delete_from dutyRollVariance
            where dutyRollVariance.ClaimCreated == NoYes::Yes
               && dutyRollVariance.CreatedDateTime < dateTimeStartMth
               && dutyRollVariance.InventTransType == InventTransType::Purch;
        ttscommit;
    }

    /// <summary>
    /// Process site
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    public void processSite(InventSiteId _siteId)
    {
        RecordInsertList dutyAdValorumClaimList;
        METDutyAdValorumClaimTmp dutyAdValorumClaimTmpLocal;

        if (!itemList.empty())
        {
            ListEnumerator iter = itemList.getEnumerator();
            dutyAdValorumClaimList = new RecordInsertList(tableNum(METDutyAdValorumClaimTmp), true, true, true, true, true, dutyAdValorumClaimTmp);

            while (iter.moveNext())
            {
                ItemId itemId = iter.current();

                dutyAdValorumClaimTmpLocal.clear();

                dutyAdValorumClaimTmpLocal.Site = _siteId;
                dutyAdValorumClaimTmpLocal.ItemId = ItemId;

                dutyAdValorumClaimList.add(dutyAdValorumClaimTmpLocal);
            }

            ttsbegin;
            dutyAdValorumClaimList.insertDatabase();
            ttscommit;
        }

    }

/// <summary>
/// Get the total number records to be processed
/// </summary>
/// <returns>Count</returns>
public int getTotalRecords()
{
    select count(RecId) from dutyAdValorumClaimTmp;
    
    return int642int(dutyAdValorumClaimTmp.RecId);
}
